func logEntryClass(severity string) string {
	switch severity {
	case "ERROR", "FATAL":
		return "log-entry-error"
	case "WARN":
		return "log-entry-warn"
	default:
		return ""
	}
}

func severityVariant(severity string) string {
	switch severity {
	case "ERROR", "FATAL":
		return "danger"
	case "WARN":
		return "warning"
	case "INFO":
		return "primary"
	default:
		return "neutral"
	}
}

func logsPaginationURL(q string, window, limit, offset int) string {
	values := url.Values{}
	if q != "" {
		values.Set("q", q)
	}
	if window != 60 {
		values.Set("window", strconv.Itoa(window))
	}
	values.Set("limit", strconv.Itoa(limit))
	values.Set("offset", strconv.Itoa(offset))
	return "/logs?" + values.Encode()
}

func hasLogDetails(log LogRow) bool {
	return log.SpanID != "" || log.ScopeName != "" || len(log.Attributes) > 0 || (log.ObservedTime != "" && log.ObservedTime != log.Time)
}

func logScopeVersion(v string) string {
	if v == "" {
		return ""
	}
	return "@" + v
}

func formatLogAttr(v any) string {
	if v == nil {
		return ""
	}
	return fmt.Sprintf("%v", v)
}

